   176→// GetSessionDir returns the directory where Gemini stores session transcripts.
   177→// Gemini stores sessions in ~/.gemini/tmp/<project-hash>/chats/
   178→func (g *GeminiCLIAgent) GetSessionDir(repoPath string) (string, error) {
   179→	// Check for test environment override
   180→	if override := os.Getenv("ENTIRE_TEST_GEMINI_PROJECT_DIR"); override != "" {
   181→		return override, nil
   182→	}
