   184→	homeDir, err := os.UserHomeDir()
   185→	if err != nil {
   186→		return "", fmt.Errorf("failed to get home directory: %w", err)
   187→	}
   188→
   189→	// Gemini uses a hash of the project path for the directory name
   190→	projectDir := SanitizePathForGemini(repoPath)
