   194→// ReadSession reads a session from Gemini's storage (JSON transcript file).
   195→// The session data is stored in NativeData as raw JSON bytes.
   196→func (g *GeminiCLIAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   197→	if input.SessionRef == "" {
   198→		return nil, errors.New("session reference (transcript path) is required")
   199→	}
   200→
   201→	// Read the raw JSON file
   202→	data, err := os.ReadFile(input.SessionRef)
   203→	if err != nil {
   204→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   205→	}
   206→
   207→	// Parse to extract computed fields
   208→	modifiedFiles, err := ExtractModifiedFiles(data)
   209→	if err != nil {
   210→		// Non-fatal: we can still return the session without modified files
   211→		modifiedFiles = nil
   212→	}
   213→
   214→	return &agent.AgentSession{
   215→		SessionID:     input.SessionID,
   216→		AgentName:     g.Name(),
   217→		SessionRef:    input.SessionRef,
   218→		StartTime:     time.Now(),
   219→		NativeData:    data,
   220→		ModifiedFiles: modifiedFiles,
   221→	}, nil
   222→}
   223→
   224→// WriteSession writes a session to Gemini's storage (JSON transcript file).
   225→// Uses the NativeData field which contains raw JSON bytes.
   226→func (g *GeminiCLIAgent) WriteSession(session *agent.AgentSession) error {
   227→	if session == nil {
   228→		return errors.New("session is nil")
   229→	}
   230→
   231→	// Verify this session belongs to Gemini CLI
   232→	if session.AgentName != "" && session.AgentName != g.Name() {
   233→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, g.Name())
   234→	}
   235→
   236→	if session.SessionRef == "" {
   237→		return errors.New("session reference (transcript path) is required")
   238→	}
   239→
   240→	if len(session.NativeData) == 0 {
   241→		return errors.New("session has no native data to write")
   242→	}
   243→
   244→	// Write the raw JSON data
   245→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   246→		return fmt.Errorf("failed to write transcript: %w", err)
   247→	}
   248→
   249→	return nil
   250→}
