   369→// TranscriptChunker interface implementation
   370→
   371→// ChunkTranscript splits a Gemini JSON transcript by distributing messages across chunks.
   372→// Gemini uses JSON format with a {"messages": [...]} structure, so chunking splits
   373→// the messages array while preserving the JSON structure in each chunk.
   374→func (g *GeminiCLIAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
   375→	var transcript GeminiTranscript
   376→	if err := json.Unmarshal(content, &transcript); err != nil {
   377→		// Fall back to JSONL chunking if not valid Gemini JSON
   378→		chunks, chunkErr := agent.ChunkJSONL(content, maxSize)
   379→		if chunkErr != nil {
   380→			return nil, fmt.Errorf("failed to chunk as JSONL: %w", chunkErr)
   381→		}
   382→		return chunks, nil
   383→	}
   384→
   385→	if len(transcript.Messages) == 0 {
   386→		return [][]byte{content}, nil
   387→	}
   388→
   389→	var chunks [][]byte
   390→	var currentMessages []GeminiMessage
   391→	currentSize := len(`{"messages":[]}`) // Base JSON structure size
   392→
   393→	for i, msg := range transcript.Messages {
   394→		// Marshal message to get its size
   395→		msgBytes, err := json.Marshal(msg)
   396→		if err != nil {
   397→			logging.Warn(context.Background(), "failed to marshal Gemini message during chunking",
   398→				slog.Int("message_index", i),
   399→				slog.String("error", err.Error()),
   400→			)
   401→			continue
   402→		}
   403→		msgSize := len(msgBytes) + 1 // +1 for comma separator
   404→
   405→		if currentSize+msgSize > maxSize && len(currentMessages) > 0 {
   406→			// Save current chunk
   407→			chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
   408→			if err != nil {
   409→				return nil, fmt.Errorf("failed to marshal chunk: %w", err)
   410→			}
   411→			chunks = append(chunks, chunkData)
   412→
   413→			// Start new chunk
   414→			currentMessages = nil
   415→			currentSize = len(`{"messages":[]}`)
   416→		}
   417→
   418→		currentMessages = append(currentMessages, msg)
   419→		currentSize += msgSize
   420→	}
   421→
   422→	// Add the last chunk
   423→	if len(currentMessages) > 0 {
   424→		chunkData, err := json.Marshal(GeminiTranscript{Messages: currentMessages})
   425→		if err != nil {
   426→			return nil, fmt.Errorf("failed to marshal final chunk: %w", err)
   427→		}
   428→		chunks = append(chunks, chunkData)
   429→	}
   430→
   431→	// Ensure we created at least one chunk (could be empty if all messages failed to marshal)
   432→	if len(chunks) == 0 {
   433→		return nil, errors.New("failed to create any chunks: all messages failed to marshal")
   434→	}
   435→
   436→	return chunks, nil
   437→}
   438→
   439→// ReassembleTranscript merges Gemini JSON chunks by combining their message arrays.
   440→func (g *GeminiCLIAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
   441→	var allMessages []GeminiMessage
   442→
   443→	for _, chunk := range chunks {
   444→		var transcript GeminiTranscript
   445→		if err := json.Unmarshal(chunk, &transcript); err != nil {
   446→			return nil, fmt.Errorf("failed to unmarshal chunk: %w", err)
   447→		}
   448→		allMessages = append(allMessages, transcript.Messages...)
   449→	}
   450→
   451→	result, err := json.Marshal(GeminiTranscript{Messages: allMessages})
   452→	if err != nil {
   453→		return nil, fmt.Errorf("failed to marshal reassembled transcript: %w", err)
   454→	}
   455→	return result, nil
   456→}
